sys_script_client.script:
function onLoad() {
  var cutoffTime = g_form.getValue('u_glide_date_time_2');
  if (cutoffTime) {
    var score = calculatePrioritizationScore(cutoffTime);
    g_form.setValue('u_prioritization_score', score);
  }
}

function calculatePrioritizationScore(cutoffTime) {

  var currentDateTime = new Date();
  var utcString = currentDateTime.toISOString(); 
  var parts = cutoffTime.split(' ');
  var dateParts = parts[0].split('-');
  var timeParts = parts[1].split(':');

// Parse components
var day = parseInt(dateParts[0], 10);
var month = parseInt(dateParts[1], 10) - 1; // JS months are 0-based
var year = parseInt(dateParts[2], 10);
var hour = parseInt(timeParts[0], 10);
var minute = parseInt(timeParts[1], 10);
var second = parseInt(timeParts[2], 10);

// Create Date object
var cutoffDate = new Date(year, month, day, hour, minute, second);
cutoffDate = cutoffDate.toISOString();
var cutoff = new Date(cutoffDate);
var diffMs = cutoff.getTime() - currentDateTime.getTime();
var diffHours = diffMs / (1000 * 60 * 60);
  if (diffHours <= 2) {
	g_form.setValue('priority', 1);
    return 100;
  } else if (diffHours <= 4) {
	g_form.setValue('priority', 2);
    return 80;
  } else if (diffHours <= 8) {
	g_form.setValue('priority', 3);
    return 50;
  } else {
	g_form.setValue('priority', 4);
    return 0; // No prioritization if more than 8 hours
  }
}
